package com.clavis.reader;
import android.content.*;import android.widget.*;import android.view.*;import org.json.*;import java.util.*;
final class CatalogScreens {
 static void info(MainActivity a){new AppDialog.Builder(a).setTitle("Catalog information").setMessage("Project Gutenberg ebooks ranked by downloads over the previous 30 days. English LibriVox audiobooks ranked by Internet Archive download counts. Initial snapshot: 26 October 2026. More titles load automatically in batches of 25, up to 1,000 per catalog. Additional ebook pages use the current Gutenberg download ranking.\n\nCatalog downloads are available without a country restriction. Source public-domain evidence covers the United States and does not establish worldwide clearance. Files retain their original licenses and source details. The app is not affiliated with these sources.").setPositiveButton("Gutenberg license",(d,n)->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.gutenberg.org/policy/license")))).setNeutralButton("LibriVox policy",(d,n)->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://librivox.org/pages/public-domain/")))).setNegativeButton("Close",null).show();}

 static void row(MainActivity a,String kind,JSONObject item,GridLayout parent){boolean audio=kind.equals("Audio");LinearLayout card=a.column();card.setPadding(a.dp(8),a.dp(6),a.dp(8),a.dp(4));card.setBackground(UiStyle.surface(a,kind,18));ImageView cover=audio?new CatalogAudioCoverView(a):new CatalogBookView(a);cover.setImageDrawable(new CatalogCover(item.optString("title"),item.optString("author"),item.optString("id"),a.serif,audio));cover.setContentDescription("Cover for "+item.optString("title"));card.addView(cover,new LinearLayout.LayoutParams(-1,a.dp(150)));FeedArtwork.bind(a,cover,CatalogRepository.artwork(item));a.space(card,4);TextView title=a.text(item.optString("title"),14,MainActivity.INK,true);title.setIncludeFontPadding(false);title.setLineSpacing(0,.92f);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(title);TextView author=a.text(item.optString("author"),12,MainActivity.MUTED,false);author.setIncludeFontPadding(false);author.setSingleLine();author.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(author);LinearLayout actions=a.row();TextView size=a.text(item.optLong("bytes")>0?android.text.format.Formatter.formatShortFileSize(a,item.optLong("bytes")):audio?"Audiobook":"EPUB",11,MainActivity.MUTED,false);size.setIncludeFontPadding(false);actions.addView(size,new LinearLayout.LayoutParams(0,-2,1));boolean downloaded=CatalogDownloads.imported(a,item.optString("id"));actions.addView(UiStyle.icon(a,downloaded?R.drawable.ic_chevron_right:R.drawable.ic_download_books,(downloaded?"Open ":"Download ")+item.optString("title"),()->CatalogDownloads.offer(a,item),36));card.addView(new View(a),new LinearLayout.LayoutParams(1,0,1));card.addView(actions);card.setOnClickListener(v->CatalogDownloads.offer(a,item));card.setOnLongClickListener(v->{StarterCatalog.rights(a,item);return true;});GridLayout.LayoutParams params=new GridLayout.LayoutParams(GridLayout.spec(GridLayout.UNDEFINED),GridLayout.spec(GridLayout.UNDEFINED,1f));params.width=0;params.height=-2;params.setGravity(android.view.Gravity.FILL);params.setMargins(a.dp(5),a.dp(5),a.dp(5),a.dp(5));parent.addView(card,params);}
 static void render(MainActivity a,String kind,String filter){a.body.removeAllViews();new Session(a,kind,filter).start();}
 static final class Session {
  final MainActivity a;final String kind,filter;final boolean audio;final LinearLayout body;final GridLayout rows;final TextView heading,footer;final HashSet<String> shown=new HashSet<>();CatalogRepository.State state;ScrollView scroll;boolean loading,failed;
  Session(MainActivity activity,String category,String query){a=activity;kind=category;filter=query.toLowerCase(Locale.ROOT);audio=kind.equals("Audio");body=a.body;rows=new GridLayout(a);rows.setColumnCount(2);heading=a.text("",18,MainActivity.INK,true);footer=a.text("",13,MainActivity.MUTED,false);footer.setGravity(android.view.Gravity.CENTER);footer.setPadding(0,a.dp(20),0,a.dp(20));}
  boolean current(){return !a.isFinishing()&&!a.isDestroyed()&&a.body==body&&body.getTag()==this;}
  void start(){body.setTag(this);a.bar.getChildAt(2).setOnClickListener(v->{EditText input=new EditText(a);input.setSingleLine();input.setText(filter);input.setHint("Search all titles and authors");new AppDialog.Builder(a).setTitle("Search catalog").setView(input).setPositiveButton("Search",(d,n)->render(a,kind,input.getText().toString().trim())).setNeutralButton("Clear",(d,n)->render(a,kind,"")).setNegativeButton("Cancel",null).show();});body.addView(heading);body.addView(a.text(filter.isEmpty()?"Popular titles · more load as you scroll":"Search across the online catalog",12,MainActivity.MUTED,false));if(kind.equals("PDF"))body.addView(a.text("Gutenberg downloads are EPUB files and appear in Ebooks. Imported and downloaded PDFs stay in My books here.",13,MainActivity.MUTED,false));a.space(body,14);body.addView(rows);body.addView(footer);footer.setOnClickListener(v->{failed=false;more();});try{state=filter.isEmpty()?CatalogRepository.load(a,audio):new CatalogRepository.State();append();}catch(Exception e){footer.setText("Catalog unavailable. Please update the app.");return;}if(body.getParent() instanceof ScrollView){scroll=(ScrollView)body.getParent();scroll.setOnScrollChangeListener((View.OnScrollChangeListener)(v,x,y,oldX,oldY)->nearBottom());if(filter.isEmpty())body.post(this::nearBottom);else more();}}
  void append(){heading.setText(filter.isEmpty()?state.items.size()+" "+(audio?"LibriVox audiobooks":"Project Gutenberg ebooks"):state.items.size()+" search results");for(JSONObject item:state.items){String id=item.optString("id");if(!shown.add(id))continue;row(a,kind,item,rows);}status();}
  void status(){footer.setText(loading?"Loading more titles…":state.items.size()>=CatalogRepository.LIMIT?"1,000 titles loaded":state.exhausted?"End of catalog":"Scroll for more titles");}
  void nearBottom(){if(!current()||scroll==null||loading||failed)return;if(body.getHeight()-scroll.getScrollY()-scroll.getHeight()<a.dp(450))more();}
  void more(){if(!current()||loading||state==null||state.exhausted||state.items.size()>=CatalogRepository.LIMIT)return;loading=true;status();CatalogRepository.worker.execute(()->{try{CatalogRepository.State next=filter.isEmpty()?CatalogRepository.next(a.getApplicationContext(),audio):CatalogRepository.search(audio,filter,state);a.handler.post(()->{if(!current())return;state=next;loading=false;failed=false;append();body.post(this::nearBottom);});}catch(Exception e){a.handler.post(()->{if(!current())return;loading=false;failed=true;footer.setText("Could not load more titles. Tap to retry.");});}});}
 }
}
